local System = _G.System
local ParserHelper = _G.wdm.WuKong.Core.PluginMethodParametersHelper
local ParserFunc = ParserHelper.__metadata__.methods[2][3]

local function parse(ts, inputs)
    local after = {}
    if #inputs > 0 then
        for i, v in pairs(inputs) do
            local t = ts[i]
            if v == "" then
                after[i] = "__null__"
            else
                after[i] = ParserFunc(t, v)
            end
        end
        -- local info = string.split(t, ".")
        -- if info[1] == "System" then
        --     local st = System[info[2]]
        --     if st then
        --         local parseFunc = st["Parse"]
        --         for i, v in pairs(inputs) do
        --             after[i] = parseFunc and parseFunc(v) or v
        --         end
        --     else
        --         if info[2] == "String[]" then
        --             for i, v in pairs(inputs) do
        --                 after[i] = System.S(v):Split(",", 0)
        --             end
        --         end
        --     end
        -- end
    end
    return after
end

return parse